      caution:["当帰飲子・四物湯（地黄を含む）：胃腸の著しく弱い人では食欲不振・胃部不快感・下痢等が出ることがある。用法は食前又は食間","<span class='sh-kufu'>臨床上の工夫（分類：院長）</span>脾虚なら食後服用や六君子湯の併用を","漢方だけでは効きが遅い。保湿外用の徹底が前提"]
