      caution:["柴胡加竜骨牡蛎湯・大柴胡湯・温清飲・抑肝散：間質性肺炎・肝機能障害の報告。咳・息切れ・発熱が出たら服用を止めてすぐ連絡するよう伝える","抑肝散・加味逍遥散も甘草を含む → 血清K・血圧を確認（偽アルドステロン症）。高齢者は減量など。抑肝散は心不全（体液貯留・急激な体重増加・息切れ等）の報告あり<span class='ref'>PMDA 添付文書：ツムラ抑肝散 11.1.3（2023年12月改訂 第1版）</span>"]
