      groups:[["肝鬱（柴胡剤）",["加味逍遥散","柴胡加竜骨牡蛎湯","抑肝散"]],["心火（清熱）",["黄連解毒湯","三黄瀉心湯"]],["肝火・肝経湿熱",["竜胆瀉肝湯"]]],
