  redTitle:"先に除外（器質的疾患・薬剤性）",
  red:[
    ["r1","血便・黒色便・便潜血陽性"],
    ["r2","50歳以上の新たな便通の変化・体重減少・貧血"],
    ["r3","大腸癌・炎症性腸疾患の家族歴"],
    ["r4","急な腹痛・嘔吐・排ガス停止（腸閉塞）"],
    ["r5","薬剤性（オピオイド・抗コリン薬・鉄剤・Ca拮抗薬・抗精神病薬）"],
    ["r6","甲状腺機能低下・糖尿病・パーキンソン病・高Ca血症"],
    ["r7","妊娠中・授乳中"]
  ],
  redMsg:r=>"器質的疾患の除外を優先してください。"
    +((r.has("r1")||r.has("r2")||r.has("r3"))?"<br>警告症状あり → 大腸内視鏡を検討。":"")
    +(r.has("r4")?"<br>腸閉塞を疑えば下剤・大黄剤は使わず、至急対応。":"")
    +(r.has("r7")?"<br>妊婦：大黄・芒硝を含む方剤は添付文書上、投与しないことが望ましい（潤腸湯・麻子仁丸も大黄を含む）。桃仁・紅花を含む方剤も同じ（流早産の危険）。"
      +"<br>授乳婦：ダイオウ中のアントラキノン誘導体が母乳に移行し、乳児の下痢を起こすことがある<span class='ref'>PMDA 添付文書：ツムラ大黄甘草湯ほか 9.6</span>":""),
  recommend(k,has){
    const why=[]; let rx;
    if(k==="shitsu"){
      if(has("hardfull")){rx="大承気湯";why.push("腹満硬痛・燥結（痞満燥実）→ 峻下。短期で");}
      else if(has("obese")){rx="防風通聖散";why.push("肥満・体格がよい実証 → 表裏双解＋通便");}
      else if(has("heat")){rx="三黄瀉心湯";why.push("のぼせ・イライラ＋便秘 → 清熱瀉下");}
      else if(has("thirst")){rx="調胃承気湯";why.push("口渇・乾燥便 → 芒硝で潤し大黄で下す（大承気湯より穏やか）");}
      else {rx="大黄甘草湯";why.push("実熱の便秘の基本形。まず最小構成から");}
      if(has("rabbit")) why.push("乾燥が強ければ麻子仁丸（①と④の橋渡し）");
    }
    if(k==="qi"){
      if(has("ibs")){rx="桂枝加芍薬大黄湯";why.push("腹痛・膨満、IBSの便秘型 → 芍薬で腸の緊張を緩め、大黄で通す");}
      else if(has("daisaiko")){rx="大柴胡湯";why.push("胸脇苦満・実証 → 柴胡・枳実で行気、大黄で通便（六磨湯に近い）");}
      else if(has("menses")){rx="加味逍遥散";why.push("月経前の悪化・のぼせ → 疏肝解鬱（出にくければ大黄甘草湯を追加）");}
      else if(has("stasis")){rx="通導散";why.push("瘀血＋気滞 → 行気・駆瘀血・通便");}
      else {rx="四逆散 ＋ 大黄甘草湯";why.push("気の詰まりを通じ、少量の大黄で通す → 六磨湯（行気導滞）の代わり");}
      if(has("stasis")&&rx!=="通導散") why.push("瘀血あり → 通導散・桃核承気湯も");
    }
    if(k==="cold"){
      if(has("daikenchu")||!has("coldpain")){rx="大建中湯";why.push("腹が冷えて張る・腸がごろごろ動く → 中焦を温め、蠕動を整える");why.push("出にくければ大黄甘草湯を少量追加");}
      else {rx="大黄甘草湯 ＋ 加工ブシ末";why.push("冷えて痛む便秘 → 温下（大黄附子湯の近似）");}
      why.push("麻黄附子細辛湯＋大黄甘草湯でも大黄附子湯（大黄・附子・細辛）を再現できるが、麻黄が入る");
    }
    if(k==="dry"){
      if(has("hinnyo")){rx="麻子仁丸";why.push("尿が多く便が硬い（脾約）→ 潤腸＋行気");}
      else if(has("bloodxu")||has("yinxu")){rx="潤腸湯";why.push("血虚・陰虚の乾燥 → 当帰・地黄で潤し、麻子仁・桃仁・杏仁で滑らせる");}
      else {rx="麻子仁丸";why.push("コロコロ便・腸の乾燥 → 潤腸通便");}
      why.push("どちらも大黄を含む（瀉下作用には個人差がある）。用法は食前又は食間");why.push("<span class='sh-kufu'>臨床上の工夫（分類：院長）</span>少量・就寝前から始める");
    }
    if(k==="weak"){
      if(has("child")){rx="小建中湯";why.push("虚弱・小児・腹痛 → 中焦を温めて補う（膠飴で緩やかに）");}
      else if(has("yangxu")){rx="補中益気湯 ＋ 八味地黄丸";why.push("脾気と腎陽をともに補う → 大補元煎（温陽益気）の代わり");}
      else {rx="補中益気湯";why.push("いきむ力がない → 升陽益気で押し出す力を補う");}
      why.push("刺激性下剤・大黄剤は避けるか最小量に。必要なら麻子仁丸を少量併用");
    }
    return {rx,why};
  },
