  cmpTitle:"便秘の5証 比較",
  cmpExtra:`<h3>治法と大黄の役割</h3>
    <div class="scroll"><table class="kv">
      <tr><th>証</th><th>治法</th><th>大黄</th></tr>
      <tr><td>① 実熱</td><td class="nw">寒下</td><td>主役（＋芒硝）</td></tr>
      <tr><td>② 気滞</td><td class="nw">行気</td><td>少量の脇役</td></tr>
      <tr><td>③ 寒</td><td class="nw">温下</td><td>附子・乾姜と組む／または使わない</td></tr>
      <tr><td>④ 腸燥</td><td class="nw">潤下</td><td>少量（麻子仁・当帰が主）</td></tr>
      <tr><td>⑤ 気虚</td><td class="nw">補益</td><td>避ける・最小限</td></tr>
    </table></div>
    <p class="hint">「大黄が効かない・腹痛が出る」は証の見直しのサイン。虚秘・寒秘に大黄を増量しても悪化しやすい。</p>`,
  pt:{
    shitsu:{t:"体の「熱」で便が乾く便秘",b:"体の中に熱がこもって腸の水分を奪い、便が硬く乾いている状態です。お腹の張りや口の渇きを伴いやすくなります。<br><br>お薬で熱を冷まし、腸を動かして便を出します。<br><br><b>生活のポイント</b>：水分をしっかりとる／辛いもの・脂っこいもの・お酒を控える／野菜・海藻をとる"},
    qi:{t:"ストレスで腸が「詰まる」便秘",b:"ストレスや緊張で気の巡りが滞り、腸の動きが止まってしまう状態です。お腹が張り、ガスが多く、出てもすっきりしません。<br><br>お薬で気の巡りを整え、腸の動きを取り戻します。<br><br><b>生活のポイント</b>：朝食後にトイレに座る習慣をつける／散歩など軽い運動／ゆっくり深呼吸"},
    cold:{t:"お腹の「冷え」で腸が固まる便秘",b:"お腹が冷えて腸の動きが鈍り、便がうまく進まない状態です。お腹が冷えて痛む、温めると楽になるのが特徴です。<br><br>お薬でお腹を内側から温め、腸を動かします。<br><br><b>生活のポイント</b>：冷たい飲食を控え、温かいものを／腹巻きでお腹を温める／朝に白湯を一杯"},
    dry:{t:"潤い不足で便が「乾く」便秘",b:"体の潤いや栄養が不足し、腸が乾いて便がコロコロになっている状態です。高齢の方や産後、病後に多く見られます。<br><br>お薬で腸を潤し、便を柔らかくして出しやすくします。<br><br><b>生活のポイント</b>：水分をこまめにとる／良い油（オリーブ油・ごま・ナッツ）を少しとる／強い下剤に頼りすぎない"},
    weak:{t:"「押し出す力」が足りない便秘",b:"便は硬くないのに、腸やお腹の力が弱くて押し出せない状態です。出たあとにぐったりすることもあります。<br><br>お薬で体の元気（気）を補い、押し出す力を取り戻します。強い下剤はかえって体力を奪うことがあります。<br><br><b>生活のポイント</b>：朝食をしっかり食べる／腹筋・足腰を無理なく鍛える／トイレで足台を使い前かがみの姿勢に"}
  },
  formulas:["大承気湯","調胃承気湯","大黄甘草湯","三黄瀉心湯","防風通聖散","桂枝加芍薬大黄湯","大柴胡湯","四逆散","加味逍遥散","通導散","大建中湯","潤腸湯","麻子仁丸","補中益気湯","八味地黄丸","小建中湯"]
