  redTitle:"先に除外（二次性頭痛の危険サイン）",
  red:[
    ["r1","突然の激しい頭痛（雷鳴頭痛）・人生最悪の頭痛"],
    ["r2","発熱・項部硬直・意識障害"],
    ["r3","麻痺・しびれ・言語障害・視野障害"],
    ["r4","50歳以上の新たな頭痛・進行性・朝の嘔吐"],
    ["r5","側頭部の圧痛・顎跛行・視力低下（巨細胞性動脈炎）"],
    ["r6","眼痛・充血・視力低下（急性緑内障）"],
    ["r7","片側の額・頭皮のピリピリ痛（帯状疱疹）"],
    ["r8","鎮痛薬を月10日以上使っている（薬物乱用頭痛）"],
    ["r9","頭部外傷後・抗凝固薬を内服中"]
  ],
  redMsg:r=>"二次性頭痛の除外を優先してください。"
    +(["r1","r2","r3","r4","r9"].some(x=>r.has(x))?"<br>至急の頭部画像検査・専門医への紹介を検討。":"")
    +(r.has("r5")?"<br>赤沈・CRPを確認し、眼科・膠原病科と連携。":"")
    +(r.has("r6")?"<br>眼科へ至急紹介。":"")
    +(r.has("r7")?"<br>皮疹の出現前でも前駆痛の可能性。抗ウイルス薬の早期投与を検討。":"")
    +(r.has("r8")?"<br>鎮痛薬の減量を並行し、漢方は予防薬として継続。":""),
  recommend(k,has){
    const why=[]; let rx;
    if(k==="gaikan"){
      if(has("windheat")){rx="川芎茶調散 ＋ 桔梗石膏";why.push("風熱 → 散風止痛＋清熱（芎芷石膏湯の近似）");why.push("顔の赤み・にきびを伴う上焦の風熱なら清上防風湯");}
      else if(has("winddamp")||has("weather")){rx="五苓散";why.push("湿邪・気象で悪化（天気痛）→ 利水で頭部の水を捌く");why.push("かぜ症状を伴えば川芎茶調散（羌活・白芷を含む）を併用");}
      else if(has("hyokyo")){rx="桂枝湯";why.push("虚弱・自汗の表寒 → 調和営衛");why.push("高齢で寒気が強く元気がなければ麻黄附子細辛湯");}
      else if(has("windcold")){rx="葛根湯";why.push("悪寒・無汗・首筋のこわばり → 風寒を発散（短期で）");why.push("頭痛が主で首こりが軽ければ川芎茶調散");}
      else {rx="川芎茶調散";why.push("かぜの頭痛・風寒 → 散風止痛");}
    }
    if(k==="kanyo"){
      if(has("menses")){rx="加味逍遥散";why.push("月経前後の悪化・のぼせ → 疏肝清熱");}
      else if(has("chotosan")||has("jokyo")){rx="釣藤散";why.push("早朝の頭痛・高血圧傾向・中高年 → 平肝熄風（天麻鈎藤飲の近似）");why.push("血虚を伴う高血圧（顔色不良）なら七物降下湯");}
      else if(has("fire")){rx="黄連解毒湯";why.push("顔面紅潮・目の充血 → 肝火・実熱を冷ます");why.push("口苦・脇痛・耳鳴りが強ければ竜胆瀉肝湯");}
      else {rx="抑肝散";why.push("イライラ・緊張・食いしばり → 平肝熄風、筋緊張をゆるめる");}
      if(has("spxu")&&rx==="抑肝散") why.push("胃腸が弱ければ抑肝散加陳皮半夏");
    }
    if(k==="tan"){
      if(has("spxu")){rx="半夏白朮天麻湯";why.push("胃腸虚弱＋頭重・めまい・悪心 → 健脾化痰熄風");}
      else if(has("goreisan")){rx="五苓散";why.push("口渇・尿不利（水毒）→ 利水");}
      else if(has("ryokei")){rx="苓桂朮甘湯";why.push("立ちくらみ・動悸 → 温陽化飲");}
      else {rx="半夏白朮天麻湯";why.push("頭重・めまい・悪心 → 化痰熄風");}
      if(has("goreisan")&&rx!=="五苓散") why.push("口渇・尿不利があれば五苓散を併用");
    }
    if(k==="oketsu"){
      if(has("trauma")){rx="通導散";why.push("頭部外傷後の頭痛 → 行気・駆瘀血（便秘がなければ治打撲一方も）");}
      else if(has("constip")){rx="桃核承気湯";why.push("瘀血＋便秘・のぼせ → 駆瘀血＋瀉下");}
      else if(has("anger")){rx="桂枝茯苓丸 ＋ 四逆散";why.push("気滞血瘀 → 血府逐瘀湯の近似");}
      else {rx="桂枝茯苓丸";why.push("固定性の刺痛・慢性 → 駆瘀血");}
      if(has("bloodxu")) why.push("血虚を伴い虚証なら当帰芍薬散");
      if(rx==="桂枝茯苓丸") why.push("ストレスで悪化するなら四逆散を併用（血府逐瘀湯の近似）");
    }
    if(k==="kanin"){
      if(has("toki4")&&!has("vomit")){rx="当帰四逆加呉茱萸生姜湯";why.push("末端の冷えで誘発 → 温経散寒");}
      else if(has("keishininjin")&&!has("vomit")){rx="桂枝人参湯";why.push("胃腸虚弱・下痢しやすい人の頭痛 → 温中＋解表");}
      else {rx="呉茱萸湯";why.push("冷え＋嘔吐を伴う発作性頭痛 → 温中降逆");why.push("発作時の頓用と、予防の継続服用の両方で使う");}
      if(has("goreisan")||has("weather")) why.push("水滞・気象で悪化するなら五苓散を併用");
    }
    if(k==="kyo"){
      if(has("kidney")){
        if(has("yang")){rx="八味地黄丸";why.push("高齢・腎精不足＋冷え → 腎陽を補う");}
        else {rx="六味丸";why.push("高齢・腎精不足、ほてり → 腎陰を補う（冷えがあれば八味地黄丸）");}
      }
      else if(has("qixu")&&has("bloodxu")){rx="十全大補湯";why.push("気血両虚 → 気血双補（八珍湯の代わり）");}
      else if(has("bloodxu")){rx="当帰芍薬散";why.push("血虚・月経後の頭痛・めまい → 養血利水");}
      else if(has("qixu")){rx="補中益気湯";why.push("疲れると悪化 → 升陽益気で清陽を頭へ");}
      else {rx="十全大補湯";why.push("持続的で軽い痛み・空虚感 → 気血双補");}
      if(has("spxu")) why.push("胃腸虚弱＋頭重・めまいなら半夏白朮天麻湯");
    }
    return {rx,why};
  },
