      caution:["茵蔯蒿湯・防風通聖散は大黄を含む → 下痢・腹痛。妊婦には投与しないことが望ましい。授乳婦：ダイオウ中のアントラキノン誘導体が母乳に移行し、乳児の下痢を起こすことがある<span class='ref'>PMDA 添付文書：ツムラ大黄甘草湯ほか 9.6</span>。山梔子も含む（長期で腸間膜静脈硬化症）"]
