      main:"四逆散／加味逍遥散／柴胡加竜骨牡蛎湯／桂枝加竜骨牡蛎湯",
      groups:[["四逆（手足の冷え＋汗）",["四逆散"]],["肝鬱化火",["加味逍遥散"]],["重鎮安神",["柴胡加竜骨牡蛎湯","桂枝加竜骨牡蛎湯"]]],
