      alt:["抑肝散：イライラ・食いしばり","半夏厚朴湯：不安・喉のつかえ","柴胡桂枝湯：緊張＋胃腸症状・虚実中間"],
      caution:["小柴胡湯・大柴胡湯・柴胡加竜骨牡蛎湯：間質性肺炎・肝機能障害の報告。咳・息切れ・発熱が出たら服用を止めてすぐ連絡するよう伝える","抗コリン外用薬と併用可。漢方単独より、西洋治療＋漢方で"]
