  cmpTitle:"多汗症の4証 比較",
  cmpExtra:`<h3>部位別：西洋治療と漢方</h3>
    <div class="scroll"><table class="kv">
      <tr><th>部位</th><th>西洋治療</th><th>漢方の視点</th></tr>
      <tr><td>腋窩</td><td>外用抗コリン薬（ソフピロニウム・グリコピロニウム）、塩化アルミニウム、ボツリヌス注射</td><td>④ 肝鬱／③ 湿熱（におい）</td></tr>
      <tr><td>手掌</td><td>外用抗コリン薬（オキシブチニン）、塩化アルミニウム、イオントフォレーシス</td><td>④ 四逆散・加味逍遥散</td></tr>
      <tr><td>足底</td><td>塩化アルミニウム、イオントフォレーシス</td><td>④／③</td></tr>
      <tr><td>頭部・顔面</td><td>塩化アルミニウム</td><td>③ 茵蔯蒿湯・黄連解毒湯／② 柴胡桂枝乾姜湯</td></tr>
      <tr><td>全身</td><td>続発性の除外が先</td><td>① 自汗／② 盗汗／③ 実熱</td></tr>
    </table></div>
    <p class="hint">自汗＝日中・動くと出る（気虚）、盗汗＝寝ている間（陰虚）、局所汗＝緊張で出る（肝鬱）。汗疱・コリン性蕁麻疹・汗で悪化するアトピーは「痒み」テーマと合わせて。</p>`,
  pt:{
    jihan:{t:"体の「バリア」が弱くて漏れる汗",b:"体の表面を守る力（衛気）が弱まっていて、少し動いただけで汗が漏れ出てしまう状態です。汗の後に寒気がしたり、かぜをひきやすかったりします。<br><br>お薬で体の表面を引き締め、汗が漏れにくい体にしていきます。<br><br><b>生活のポイント</b>：汗をかいたらすぐ拭く・着替える／無理のない運動で体力をつける／よく眠る"},
    tohan:{t:"潤い不足による「寝汗」",b:"体の潤いが不足して内側に熱がこもり、眠っている間に汗が出てしまう状態です。手足のほてりや口の乾きを伴いやすくなります。<br><br>お薬で潤いを補い、こもった熱を静めます。<br><br><b>生活のポイント</b>：夜更かしを避ける／辛いもの・お酒を控える／寝室を暑くしすぎない"},
    netsu:{t:"体の「熱」が汗を押し出す多汗",b:"体の中に熱や湿気がこもり、それが汗として押し出されている状態です。暑がりで汗が多く、汗がべたついたり、においが気になったりします。<br><br>お薬で体の中の熱と湿気を冷まし、外へ出していきます。<br><br><b>生活のポイント</b>：脂っこいもの・甘いもの・辛いもの・お酒を控える／通気性のよい服を／こまめにシャワー"},
    kanutsu:{t:"緊張やストレスで出る汗",b:"緊張やストレスで気の巡りが乱れ、手のひら・足の裏・脇などに汗が出やすくなっている状態です。手足は冷たいのに汗ばむこともあります。<br><br>お薬で気の巡りを整え、緊張をゆるめます。塗り薬などの治療と一緒に行うと効果的です。<br><br><b>生活のポイント</b>：深呼吸で緊張をほどく／カフェインを控えめに／汗を気にしすぎない工夫（ハンカチ・制汗剤）"}
  },
  formulas:["防己黄耆湯","桂枝加黄耆湯","補中益気湯","黄耆建中湯","六味丸","温清飲","柴胡桂枝乾姜湯","白虎加人参湯","茵蔯蒿湯","竜胆瀉肝湯","黄連解毒湯","防風通聖散","四逆散","加味逍遥散","柴胡加竜骨牡蛎湯","桂枝加竜骨牡蛎湯"]
