  redMsg:r=>"器質的疾患の除外を優先してください。"
    +((r.has("r1")||r.has("r2")||r.has("r3"))?"<br>胸部X線（必要ならCT）・喀痰検査を。":"")
    +(r.has("r4")?"<br>抗菌薬など西洋治療を優先。":"")
    +(r.has("r5")?"<br>呼吸機能検査・心エコー・BNPを検討。":"")
    +(r.has("r6")?"<br>ARBなど他剤への変更を検討。":"")
    +(r.has("r7")?"<br>PPIの診断的投与も選択肢。":""),
  recommend(k,has){
    const why=[]; let rx;
    if(k==="hi"){
      if(has("spxu")){rx="六君子湯";why.push("胃腸虚弱＋痰 → 二陳湯＋四君子湯で、生痰の源（脾）を補う");}
      else {rx="二陳湯";why.push("白く粘る痰・悪心 → 燥湿化痰の基本方");}
      if(has("baikaku")) why.push("喉のつかえ（梅核気）があれば半夏厚朴湯を併用");
    }
    if(k==="hai"){
      if(has("gaihan")){rx="小青竜湯";why.push("悪寒・くしゃみ・水様の痰 → 外寒内飲を宣肺・温化");}
      else if(has("saiboku")){rx="柴朴湯";why.push("ストレスで悪化する慢性の咳・喘息 → 小柴胡湯＋半夏厚朴湯");}
      else if(has("baikaku")){rx="半夏厚朴湯";why.push("喉のつかえ・胸苦しさ・不安 → 行気降逆・化痰");}
      else if(has("bakumon")){rx="麦門冬湯";why.push("発作的な咳き込み・痰が切れにくい・喉の乾き → 潤肺降逆");}
      else if(has("wheeze")){rx="神秘湯";why.push("喘鳴・呼吸困難 → 宣肺平喘（麻黄を含む）");}
      else if(has("sanso")){rx="参蘇飲";why.push("虚弱な人のかぜ後の咳・痰、胃腸症状 → 扶正解表・化痰");}
      else {rx="半夏厚朴湯";why.push("痰が喉にからむ咳 → 降気化痰");}
    }
    if(k==="netsu"){
      if(has("nose")){rx="辛夷清肺湯";why.push("後鼻漏・鼻閉・黄色い鼻汁 → 肺熱を冷まし鼻竅を通じる");why.push("にきび体質・慢性副鼻腔炎なら荊芥連翹湯");}
      else if(has("tonsil")){rx="小柴胡湯加桔梗石膏";why.push("扁桃の腫れ・咽頭痛 → 和解＋清熱排膿");}
      else if(has("makyo")){rx="麻杏甘石湯";why.push("咳き込み・喘鳴・汗・口渇 → 肺熱を冷まして平喘（咳が主なら五虎湯）");}
      else if(has("chikujo")){rx="竹茹温胆湯";why.push("かぜの後の咳・痰・不眠 → 清熱化痰（黄連温胆湯の代わり）");}
      else {rx="清肺湯";why.push("黄色く粘る痰・長引く咳 → 清熱化痰・潤肺（清金化痰湯の代わり）");}
    }
    if(k==="jin"){
      if(has("ryokan")){rx="苓甘姜味辛夏仁湯";why.push("胃腸が弱く麻黄が合わない寒飲 → 小青竜湯から麻黄を抜いた方意");}
      else if(has("mafusai")){rx="麻黄附子細辛湯";why.push("高齢・元気がない・寒気 → 陽虚＋外寒");}
      else if(has("gaihan")){rx="小青竜湯";why.push("悪寒・くしゃみ・水様の痰 → 外寒内飲");}
      else if(has("hachimi")){rx="八味地黄丸";why.push("夜間頻尿・腰膝の冷え・動くと息切れ → 腎陽を補い納気");}
      else if(has("shinbu")){rx="真武湯";why.push("むくみ・めまい・動悸・下痢 → 温陽利水（腎陽虚の水泛）");}
      else if(has("watery")){rx="小青竜湯";why.push("水様の痰・鼻水 → 温肺化飲");}
      else {rx="真武湯";why.push("冷えを伴う水飲 → 腎陽を温めて水を捌く");}
    }
    return {rx,why};
  },
