  recommend(k,has){
    const why=[]; let rx;
    if(k==="tan"){
      if(has("shinbu")){rx="真武湯";why.push("冷え・下痢・ふらついて倒れそう → 温陽利水（振振欲擗地）");}
      else if(has("goreisan")){
        if(has("saiko")){rx="柴苓湯";why.push("水滞＋ストレス・口苦 → 小柴胡湯＋五苓散");}
        else {rx="五苓散";why.push("回転性・口渇・尿不利・耳閉感 → 利水（沢瀉湯の方意を含む）");}
      }
      else if(has("ryokei")){rx="苓桂朮甘湯";why.push("立ちくらみ・動悸・のぼせ（気上衝）→ 温陽化飲・降逆");}
      else if(has("tannetsu")){rx="竹茹温胆湯";why.push("イライラ・不眠・黄色い痰 → 痰湿化火を清す（黄連温胆湯の代わり）");}
      else if(has("tokishaku")){rx="当帰芍薬散";why.push("若い女性の血虚＋水滞 → 養血利水");}
      else {rx="半夏白朮天麻湯";why.push("頭重・悪心・胃腸虚弱 → 健脾化痰熄風");}
      if(has("spxu")&&rx!=="半夏白朮天麻湯") why.push("胃腸虚弱が強ければ半夏白朮天麻湯を併用");
    }
    if(k==="kan"){
      if(has("fire")){rx="竜胆瀉肝湯";why.push("顔面紅潮・目の充血・口苦 → 肝火を冷ます");}
      else if(has("shichimotsu")){rx="七物降下湯";why.push("血虚を伴う高血圧 → 養血＋平肝");}
      else if(has("meno")){rx="女神散";why.push("更年期ののぼせ・めまい → 理気＋清熱（加味逍遥散も候補）");}
      else if(has("ryukotsu")){rx="柴胡加竜骨牡蛎湯";why.push("不安・動悸・不眠 → 疏肝＋重鎮安神");}
      else if(has("yokukan")){rx="抑肝散";why.push("ふるえ・筋のこわばり・食いしばり（肝風）→ 平肝熄風");}
      else {rx="釣藤散";why.push("頭痛・高血圧・肩こりを伴うめまい → 平肝熄風（天麻鈎藤飲の代わり）");}
      if(has("spxu")&&rx==="抑肝散") why.push("胃腸が弱ければ抑肝散加陳皮半夏");
    }
    if(k==="kyo"){
      if(has("kihi")){rx=has("mildheat")?"加味帰脾湯":"帰脾湯";why.push("不眠・不安・動悸・物忘れ → 心脾を補う"+(has("mildheat")?"（ほてり・イライラ → 柴胡・山梔子を加えた加味帰脾湯）":""));}
      else if(has("bloodxu")){rx="十全大補湯";why.push("顔色不良・出血傾向・病後 → 気血双補（八珍湯の代わり）");}
      else {rx="補中益気湯";why.push("疲労で悪化・起立性低血圧 → 升陽益気で清陽を頭へ");}
    }
    if(k==="jin"){
      if(has("shinbu")){rx="真武湯";why.push("冷え・下痢・倒れそうなふらつき → 腎陽虚の水泛を温陽利水");}
      else if(has("yang")){rx="八味地黄丸";why.push("冷え・夜間頻尿 → 腎陽を補う（右帰丸の代わり）");why.push("水様の下痢・ふらつきが強ければ真武湯");}
      else {rx="六味丸";why.push("腎精・腎陰の不足 → 滋腎（左帰丸・杞菊地黄丸の代わり）");}
      if(has("eye")) why.push("目のかすみ＋頭痛・高血圧があれば釣藤散（菊花を含む）を併用 → 杞菊地黄丸の方意に近づく");
    }
    return {rx,why};
  },
