  recommend(k,has){
    const why=[]; let rx;
    if(k==="hai"){
      rx="清上防風湯";why.push("顔の上部の赤い丘疹 → 上焦の風熱を散らして冷ます（にきびの代表方）");
      if(has("thirst")) why.push("口渇・ほてりが強ければ白虎加人参湯を併用");
      if(has("faceheat")&&!has("thirst")) why.push("赤み・熱感が強ければ黄連解毒湯を併用");
      if(has("pus")) why.push("膿疱が多ければ排膿散及湯を併用");
    }
    if(k==="shitsu"){
      if(has("obese")){rx="防風通聖散";why.push("肥満・便秘の実証 → 表裏双解");}
      else if(has("keigai")){rx="荊芥連翹湯";why.push("浅黒い肌・慢性・鼻炎や扁桃炎 → 解毒証体質を改善");}
      else if(has("pus")&&has("jumi")){rx="十味敗毒湯";why.push("化膿傾向の初期 → 散風・排膿（体質改善）");why.push("膿疱・硬結が強ければ排膿散及湯を併用");}
      else if(has("pus")){rx="排膿散及湯";why.push("膿疱・硬結 → 排膿（十味敗毒湯・荊芥連翹湯と併用も）");}
      else if(has("jumi")){rx="十味敗毒湯";why.push("化膿傾向・体質改善 → 散風・排膿");}
      else if(has("gastric")){rx="半夏瀉心湯";why.push("胃もたれ・口内炎 → 脾胃の湿熱を和す");}
      else {rx="荊芥連翹湯";why.push("湿熱・化膿しやすいニキビ → 解毒・清熱");}
    }
    if(k==="netsu"){
      if(has("tokishaku")){rx="当帰芍薬散";why.push("冷え・色白・むくみ・虚弱 → 虚証の血虚・瘀血＋水滞");}
      else if(has("toukaku")){rx="桃核承気湯";why.push("便秘・のぼせの実証 → 駆瘀血＋瀉下");}
      else if(has("stress")){rx="加味逍遥散";why.push("月経前の悪化・イライラ・のぼせ → 疏肝清熱");}
      else if(has("unsei")){rx="温清飲";why.push("乾燥＋赤み → 血熱と血虚を同時に");}
      else {rx="桂枝茯苓丸加薏苡仁";why.push("暗赤色・色素沈着・月経との関連 → 駆瘀血＋薏苡仁で肌を整える");}
      if(has("chronic")&&rx!=="桂枝茯苓丸加薏苡仁") why.push("硬結・瘢痕には桂枝茯苓丸加薏苡仁を併用");
    }
    return {rx,why};
  },
