  cmpTitle:"ニキビの3証 比較",
  cmpExtra:`<h3>皮疹と部位で見る</h3>
    <div class="scroll"><table class="kv">
      <tr><th>皮疹・部位</th><th>証と方剤</th></tr>
      <tr><td>赤い丘疹・額や頬（上焦）</td><td>① 清上防風湯</td></tr>
      <tr><td>膿疱・化膿・脂っこい食事で悪化</td><td>② 十味敗毒湯・排膿散及湯・荊芥連翹湯</td></tr>
      <tr><td>口周り・あご・背中</td><td>② 脾胃湿熱</td></tr>
      <tr><td>下顎・フェイスライン・月経前</td><td>③ 加味逍遥散・桂枝茯苓丸加薏苡仁</td></tr>
      <tr><td>暗赤色・色素沈着・硬結・瘢痕</td><td>③ 桂枝茯苓丸加薏苡仁</td></tr>
    </table></div>
    <p class="hint">急性の炎症期は①②、慢性化・痕は③。漢方は外用・内服の標準治療と併用し、体質面から補う位置づけ。</p>`,
  pt:{
    hai:{t:"顔にこもった「熱」によるニキビ",b:"顔や頭など体の上のほうに熱がこもり、赤く炎症を起こしたニキビができている状態です。額・鼻・頬に出やすく、顔のほてりを伴うこともあります。<br><br>お薬で顔の熱を冷まし、炎症を鎮めます。塗り薬と一緒に続けることが大切です。<br><br><b>生活のポイント</b>：辛いもの・揚げ物・甘いものを控える／睡眠をしっかりとる／洗顔は優しく1日2回"},
    shitsu:{t:"胃腸の「湿気と熱」による化膿しやすいニキビ",b:"脂っこいものや甘いもの、お酒などで胃腸に湿気と熱がたまり、それが肌にあふれて、膿をもちやすいニキビになっている状態です。口の周りやあご、背中にも出やすくなります。<br><br>お薬で体の中の湿気と熱を取り除き、化膿しにくい肌にします。<br><br><b>生活のポイント</b>：脂っこいもの・甘いもの・乳製品・お酒を控える／便通を整える／夜遅い食事を避ける"},
    netsu:{t:"血の巡りの「滞り」によるニキビ",b:"血の流れが滞り（瘀血）、赤黒いニキビや跡が残りやすくなっている状態です。月経前に悪化したり、あごやフェイスラインに出やすかったりするのが特徴です。<br><br>お薬で血の巡りをよくし、ニキビ跡や繰り返すニキビを改善します。<br><br><b>生活のポイント</b>：体を冷やさない／適度な運動で巡りをよくする／ストレスをためない／ニキビを触らない・つぶさない"}
  },
  formulas:["清上防風湯","黄連解毒湯","白虎加人参湯","荊芥連翹湯","十味敗毒湯","排膿散及湯","防風通聖散","半夏瀉心湯","桂枝茯苓丸加薏苡仁","加味逍遥散","当帰芍薬散","桃核承気湯","温清飲"]
