  recommend(k,has){
    const why=[]; let rx;
    if(k==="utsu"){
      if(has("keiryu")){rx="桂枝加竜骨牡蛎湯";why.push("虚弱・神経過敏・寝汗 → 陰陽を調和し、竜骨・牡蛎で鎮める");}
      else if(has("ryukotsu")){rx="柴胡加竜骨牡蛎湯";why.push("不安・不眠・動悸 → 疏肝＋重鎮安神");}
      else if(has("meno")){rx="加味逍遥散";why.push("月経前の悪化・のぼせ → 疏肝清熱＋養血");}
      else if(has("daisaiko")){rx="大柴胡湯";why.push("胸脇苦満・便秘の実証 → 疏肝＋瀉下");}
      else {rx="柴胡加竜骨牡蛎湯";why.push("ストレス・ショック後の脱毛 → 疏肝＋安神（円形脱毛症で頻用）");}
      if(has("stasis")) why.push("瘀血所見あり → 桂枝茯苓丸を併用");
    }
    if(k==="kyo"){
      if(has("kihi")){rx="加味帰脾湯";why.push("不眠・不安・考えすぎ → 心脾を補い、血を養う");}
      else if(has("tokishaku")){rx="当帰芍薬散";why.push("冷え・むくみ・月経不順 → 養血利水");}
      else if(has("dryscalp")){rx="当帰飲子";why.push("頭皮の乾燥・フケ・かゆみ → 養血潤燥・熄風（何首烏を含む）");}
      else {rx="十全大補湯";why.push("顔色不良・疲れやすい → 気血双補（髪は血の余り）");}
      if(has("qixu")&&rx!=="十全大補湯") why.push("疲労・産後・病後の要素が強ければ十全大補湯を併用");
    }
    if(k==="netsu"){
      if(has("youth")){rx="柴胡清肝湯";why.push("小児〜思春期・扁桃炎を繰り返す → 解毒証体質");}
      else if(has("itch")){rx="消風散";why.push("かゆみ・脂っぽい頭皮・アトピー合併 → 散風・清熱・燥湿");}
      else if(has("heat")){rx="黄連解毒湯";why.push("のぼせ・口渇・赤み → 清熱瀉火");}
      else {rx="温清飲";why.push("頭皮の赤み＋乾燥 → 清熱涼血＋養血（涼血消風散の代わり）");}
      if(has("rapid")) why.push("急速進行・多発は標準治療を優先し、漢方は併用で");
    }
    if(k==="jin"){
      if(has("yang")){rx="八味地黄丸";why.push("冷え・夜間頻尿 → 腎陽を補う");}
      else {rx="六味丸";why.push("慢性・再発・白髪 → 肝腎の精血を補う（七宝美髯丹の代わり）");}
      if(has("qixu")) why.push("気力・体力も低下 → 十全大補湯（または人参養栄湯）を併用");
      why.push("何首烏を含む当帰飲子の併用も（七宝美髯丹の方意に近づく）");
    }
    return {rx,why};
  },
  addons:(has,top)=>top?`<div class="addon combo"><b>併用の基本</b>：病型・重症度に応じて標準治療（ステロイド外用・局注、局所免疫療法、冷却療法、JAK阻害薬など）を選び、漢方は体質面から併用。効果判定は3〜6か月を目安に。</div>`:"",
