      caution:["地黄を含む方剤：胃腸の著しく弱い人では食欲不振・胃部不快感・下痢等。用法は食前又は食間","<span class='sh-kufu'>臨床上の工夫（分類：院長）</span>胃腸が弱ければ食後に","八味地黄丸は附子を含む"]
