  redTitle:"先に除外（肩こりに隠れる疾患）",
  red:[
    ["r1","左肩〜腕の痛み・胸痛・冷汗・労作で悪化（狭心症・心筋梗塞）"],
    ["r2","手のしびれ・脱力・細かい作業がしにくい（頸椎症）"],
    ["r3","突然の激しい首の痛み・頭痛（くも膜下出血・椎骨動脈解離）"],
    ["r4","発熱・夜間痛・体重減少（感染・腫瘍）"],
    ["r5","高齢で両肩・上腕の朝のこわばり（リウマチ性多発筋痛症）"],
    ["r6","肩関節の可動域制限（五十肩・腱板断裂）"],
    ["r7","片側のピリピリした痛み（帯状疱疹の前駆痛）"],
    ["r8","高血圧・眼精疲労・顎関節症・うつの背景"]
  ],
  redMsg:r=>"器質的疾患の除外を優先してください。"
    +(r.has("r1")?"<br>至急、心電図と循環器科での評価を。":"")
    +(r.has("r2")?"<br>整形外科で頸椎の評価（MRI）を。":"")
    +(r.has("r3")?"<br>救急対応を。":"")
    +(r.has("r4")?"<br>血液検査・画像で精査を。":"")
    +(r.has("r5")?"<br>CRP・赤沈を確認。少量ステロイドが著効しやすい。":"")
    +(r.has("r6")?"<br>整形外科での評価を（漢方では④の二朮湯も）。":"")
    +(r.has("r7")?"<br>皮疹が出る前でも、抗ウイルス薬の早期投与を検討。":"")
    +(r.has("r8")?"<br>背景の治療を並行（高血圧なら②の釣藤散も）。":""),
  recommend(k,has){
    const why=[]; let rx;
    if(k==="gai"){
      if(has("mafusai")){rx="麻黄附子細辛湯";why.push("高齢・虚弱で寒気が強い → 陽虚＋外寒");}
      else if(has("jutsubu")&&!has("acute")){rx="桂枝加朮附湯";why.push("慢性の冷えで関節・筋肉も痛む → 温経散寒・除湿");}
      else if(has("hyokyo")&&!has("acute")){rx="桂枝加葛根湯";why.push("汗が出やすい虚弱な人の項背のこわばり → 桂枝湯＋葛根");}
      else {rx="葛根湯";why.push("急性の首筋〜肩のこわばり・悪寒・無汗 → 風寒を発散し、項背をゆるめる");}
      if(rx==="葛根湯") why.push("麻黄を含むため短期で。慢性の肩こりに漫然と続けない");
    }
    if(k==="oketsu"){
      if(has("daisaiko")){rx="大柴胡湯";why.push("胸脇苦満・便秘の実証 → 疏肝＋瀉下");}
      else if(has("meno")){rx="加味逍遥散";why.push("月経前の悪化・のぼせ → 疏肝清熱＋養血");}
      else if(has("kuishibari")){rx="抑肝散";why.push("食いしばり・イライラ → 平肝熄風、筋の緊張をゆるめる");}
      else if(has("stress")){rx="四逆散";why.push("ストレス・脇の張り → 疏肝理気（柴胡疏肝散の代わり）");}
      else if(has("choto")){rx="釣藤散";why.push("中高年・高血圧・頭痛 → 平肝熄風");}
      else if(has("shibire")){rx="疎経活血湯";why.push("しびれ・痛みを伴う → 活血・祛風湿");}
      else {rx="桂枝茯苓丸";why.push("同じ姿勢・拒按・夜間に悪化 → 駆瘀血");}
      if(rx!=="桂枝茯苓丸") why.push("同じ姿勢・拒按の瘀血があれば桂枝茯苓丸を併用");
      if(has("cramp")) why.push("急なつり・こわばりには芍薬甘草湯（甘草が多い（1日6g）ので、続けるときは血清K・血圧を確認）");
    }
    if(k==="kyo"){
      if(has("goshuyu")){rx="呉茱萸湯";why.push("冷え・反復する頭痛・吐き気 → 温中降逆（中寒・寒飲）");}
      else if(has("kidney")){rx="八味地黄丸";why.push("高齢・腰膝のだるさ → 肝腎を補い、筋骨を養う");}
      else if(has("tokishaku")){rx="当帰芍薬散";why.push("冷え・むくみ・月経不順 → 養血利水");}
      else if(has("kenchu")){rx="黄耆建中湯";why.push("虚弱・疲れると寝汗・腹痛 → 中焦を温めて補う");}
      else if(has("bloodxu")){rx="十全大補湯";why.push("顔色不良・目のかすみ → 気血双補（肝血で筋を養う）");}
      else {rx="補中益気湯";why.push("疲労で悪化・喜按 → 升陽益気（脾は肌肉を主る）");}
    }
    if(k==="tan"){
      if(has("nijutsu")){rx="二朮湯";why.push("肩関節の痛み・腕が上がらない → 化痰祛湿・通絡（五十肩で頻用）");}
      else if(has("boi")){rx="防己黄耆湯";why.push("水太り・汗かき・関節痛 → 益気利水");}
      else if(has("goreisan")){rx="五苓散";why.push("むくみ・口渇・尿不利 → 利水");}
      else if(has("ryokei")){rx="苓桂朮甘湯";why.push("立ちくらみ・動悸 → 温陽化飲");}
      else {rx="半夏白朮天麻湯";why.push("板が乗ったような重さ・頭重・悪心 → 健脾化痰");}
    }
    return {rx,why};
  },
  addons:(has,top)=>top?`<div class="addon combo"><b>併用</b>：鍼灸・円皮鍼（肩井・風池・天柱・肩外兪など）、温罨法、ストレッチと組み合わせると効果を実感しやすい。</div>`:"",
