      tcm:[["桂枝茯苓丸・芍薬甘草湯","医療用エキスあり（そのまま）"],["柴胡疏肝散（四逆散＋川芎・香附子・陳皮）","医療用エキスなし → 四逆散で近似"],["身痛逐瘀湯","医療用エキスなし → 疎経活血湯"]],
      alt:["通導散：瘀血＋便秘の実証","治打撲一方：打撲・寝違えの後","葛根湯：急性の寝違え（短期）"],
      caution:["芍薬甘草湯は甘草が多い（1日6g）→ 偽アルドステロン症・低K。うっ血性心不全・心室細動・心室頻拍の報告あり（動悸・息切れ・倦怠感・めまい・失神等で中止）。血清K・血圧を確認<span class='ref'>PMDA 添付文書：ツムラ芍薬甘草湯 11.1.2・11.1.3（2023年12月改訂 第1版）</span>","抑肝散：心不全（体液貯留・急激な体重増加・息切れ等）の報告あり<span class='ref'>PMDA 添付文書：ツムラ抑肝散 11.1.3（2023年12月改訂 第1版）</span>","大柴胡湯は黄芩、加味逍遥散は山梔子を含む"]
