  redTitle:"先に確認（耳鼻咽喉科的な除外）",
  red:[
    ["r1","強い咽頭痛・飲み込めない・呼吸が苦しい・含み声（急性喉頭蓋炎）"],
    ["r2","2週間以上続く声がれ・喫煙や飲酒の習慣（喉頭癌・声帯病変）"],
    ["r3","甲状腺・胸部の手術後、または原因不明の片側性の声がれ（反回神経麻痺）"],
    ["r4","血痰・首のしこり・体重減少"],
    ["r5","胸やけ・呑酸・咳払いが多い（咽喉頭酸逆流）"],
    ["r6","吸入ステロイドを使用中"],
    ["r7","寒がり・むくみ・声が低くなった（甲状腺機能低下症）"],
    ["r8","手のふるえ・動作緩慢・飲み込みにくさ（神経疾患）"]
  ],
  redMsg:r=>"2週間以上続く声がれは、耳鼻科で喉頭の観察を。"
    +(r.has("r1")?"<br>急性喉頭蓋炎は気道閉塞の危険がある → 至急、救急・耳鼻科へ。":"")
    +(r.has("r2")||r.has("r4")?"<br>喉頭内視鏡で悪性疾患を除外。":"")
    +(r.has("r3")?"<br>反回神経麻痺の原因（肺癌・食道癌・甲状腺癌・大動脈瘤など）を精査。":"")
    +(r.has("r5")?"<br>PPIの診断的投与も選択肢。":"")
    +(r.has("r6")?"<br>吸入後のうがい・スペーサーの使用、吸入薬の種類の見直しを。":"")
    +(r.has("r7")?"<br>TSH・FT4を確認。":"")
    +(r.has("r8")?"<br>神経内科と連携。":""),
  recommend(k,has){
    const why=[]; let rx;
    if(k==="gai"){
      if(has("mafusai")){rx="麻黄附子細辛湯";why.push("高齢・寒気が強い急な失声 → 少陰の寒を温めて散らす");}
      else if(has("windcold")){rx="麻黄湯";why.push("悪寒・無汗の風寒 → 宣肺散寒（三拗湯＋桂皮。短期で）");}
      else if(has("tonsil")){rx="小柴胡湯加桔梗石膏";why.push("扁桃の腫れ・強い咽頭痛 → 和解＋清熱利咽");}
      else if(has("tannetsu")){rx="麻杏甘石湯";why.push("黄色い痰・咳込み → 肺熱を冷まし宣肺");}
      else if(has("dry")){rx="麦門冬湯";why.push("喉の乾燥・空咳（燥邪）→ 潤肺（清燥救肺湯の代わり）");}
      else {rx="桔梗湯";why.push("急性の声がれ・咽頭痛 → 利咽・排膿（うがいをしながら飲む）");}
      if(rx!=="桔梗湯"&&has("throat")) why.push("咽頭痛があれば桔梗湯を併用");
    }
    if(k==="kanka"){
      if(has("fire")){rx="竜胆瀉肝湯";why.push("怒り・顔面紅潮・口苦 → 肝火を冷ます（のぼせが主なら黄連解毒湯）");}
      else if(has("kanbaku")){rx="甘麦大棗湯";why.push("悲しみ・感情の揺れ → 心を養い、急迫を緩める");}
      else if(has("baikaku")){rx="半夏厚朴湯";why.push("喉のつかえ・心因性 → 行気散結（咽中炙臠）");}
      else if(has("meno")){rx="加味逍遥散";why.push("月経・更年期と関連 → 疏肝清熱");}
      else {rx="加味逍遥散";why.push("ストレスで声が出ない → 疏肝解鬱＋清熱");}
      if(has("baikaku")&&rx!=="半夏厚朴湯") why.push("喉のつかえがあれば半夏厚朴湯を併用");
      why.push("心因性失声は、器質的疾患を耳鼻科で除外したうえで");
    }
    if(k==="oketsu"){
      if(has("constip")){rx="桃核承気湯";why.push("瘀血＋便秘・のぼせ → 駆瘀血＋瀉下");}
      else {rx="桂枝茯苓丸 ＋ 桔梗湯";why.push("慢性に枯れた声・声帯の血行障害 → 活血＋利咽（会厭逐瘀湯の近似）");}
      why.push("声帯結節・ポリープは耳鼻科で評価し、音声治療（発声指導）と併用");
    }
    if(k==="yin"){
      if(has("kidney")){rx="麦門冬湯 ＋ 六味丸";why.push("肺腎陰虚・高齢 → 肺を潤し腎陰を補う（百合固金湯の近似）");}
      else if(has("night")||has("hot")){rx="滋陰降火湯";why.push("夜に悪化・ほてり → 滋陰潤肺・降火");}
      else {rx="麦門冬湯";why.push("喉の乾燥・声の使いすぎ → 潤肺利咽");}
    }
    if(k==="kyo"){
      if(has("ninjin")){rx="人参養栄湯";why.push("高齢・咳・物忘れ → 気血を補い、肺を養う");}
      else if(has("spxu")){rx="六君子湯";why.push("胃腸虚弱 → 脾を補い、肺気の源をつくる（培土生金）");}
      else {rx="補中益気湯";why.push("声に力がない・疲れると悪化 → 升陽益気で精気を喉へ");}
    }
    return {rx,why};
  },
