  cmpTitle:"声がれの5証 比較",
  cmpExtra:`<h3>金実不鳴と金破不鳴</h3>
    <div class="scroll"><table class="kv">
      <tr><th></th><th>金実不鳴（実）</th><th>金破不鳴（虚）</th></tr>
      <tr><td>病機</td><td>邪気が肺を塞ぎ、気門へ精気が届かない</td><td>肺・腎・脾の気陰が消耗し、喉を養えない</td></tr>
      <tr><td>経過</td><td>急性。急に声が止まる。かぜ・ストレスが引き金</td><td>慢性。疲れると悪化。かすれ声・弱々しい声</td></tr>
      <tr><td>証</td><td>①外邪 ②肝火 ③瘀血</td><td>④肺腎陰虚 ⑤脾肺気虚</td></tr>
      <tr><td>方剤</td><td>桔梗湯・麻杏甘石湯・半夏厚朴湯・桂枝茯苓丸</td><td>麦門冬湯・滋陰降火湯・補中益気湯</td></tr>
    </table></div>
    <h3 style="margin-top:14px">声の出方で見る</h3>
    <div class="scroll"><table class="kv">
      <tr><th>声の出方</th><th>証</th></tr>
      <tr><td>かぜの後、急に出なくなる</td><td>① 外邪犯肺</td></tr>
      <tr><td>ストレスの後・喉のつかえ</td><td>② 肝火・気鬱</td></tr>
      <tr><td>慢性・枯れたまま・結節</td><td>③ 瘀血</td></tr>
      <tr><td>夕方〜夜・乾燥・使いすぎ</td><td>④ 肺腎陰虚</td></tr>
      <tr><td>小さい・力がない・疲れると</td><td>⑤ 脾肺気虚</td></tr>
    </table></div>`,
  pt:{
    gai:{t:"かぜなど「外から」の原因による声がれ",b:"かぜや乾燥した空気などで、喉の通り道が塞がれたり乾いたりして、急に声がかれた状態です。東洋医学では、鐘が詰まって鳴らない状態にたとえます。<br><br>お薬で喉の炎症や詰まりを取り、声の通り道を回復させます。<br><br><b>生活のポイント</b>：声を休める（ささやき声も負担）／加湿・こまめな水分／温かい飲み物でのどを潤す"},
    kanka:{t:"ストレスで「喉が詰まる」声がれ",b:"ストレスや強い感情で気の巡りが滞り、喉に熱がのぼったり、詰まった感じが出たりして、声が出にくくなっている状態です。<br><br>お薬で気の巡りを整え、喉の詰まりと熱を取ります。<br><br><b>生活のポイント</b>：ゆっくり深呼吸／気持ちを吐き出せる時間をつくる／十分な睡眠"},
    oketsu:{t:"喉の「血の巡りの滞り」による声がれ",b:"炎症が長引いたり、声を使いすぎたりして、喉の血の巡りが滞り、声がかれたまま戻りにくくなっている状態です。<br><br>お薬で喉の血の巡りをよくします。声帯の状態によっては、耳鼻科での治療や発声の指導と一緒に行います。<br><br><b>生活のポイント</b>：声の使いすぎを避ける／大声・咳払いを控える／首を冷やさない"},
    yin:{t:"喉の「潤い不足」による声がれ",b:"体の潤いが不足して喉が乾き、声帯がうまく震えなくなっている状態です。声を使いすぎたときや、夕方から夜にかけて悪化しやすいのが特徴です。<br><br>お薬で喉と体の潤いを補います。<br><br><b>生活のポイント</b>：加湿・こまめな水分／白い食材（梨・大根・蓮根・はちみつ）で潤す／夜更かし・辛いもの・お酒を控える"},
    kyo:{t:"「声を押し出す力」が足りない声がれ",b:"胃腸が弱ってエネルギー（気）が不足し、声を喉まで押し出す力が弱くなっている状態です。声が小さく、疲れると出にくくなるのが特徴です。<br><br>お薬で胃腸とエネルギーを補い、声に力を取り戻します。<br><br><b>生活のポイント</b>：三食しっかり食べる／十分な休息／腹式呼吸で声を支える練習を"}
  },
  formulas:["桔梗湯","小柴胡湯加桔梗石膏","麻黄湯","麻黄附子細辛湯","麦門冬湯","麻杏甘石湯","清肺湯","竜胆瀉肝湯","黄連解毒湯","加味逍遥散","半夏厚朴湯","甘麦大棗湯","桂枝茯苓丸","桃核承気湯","滋陰降火湯","六味丸","補中益気湯","六君子湯","人参養栄湯"]
