    "hai+hi":"脾肺両虚（土生金：脾が弱ると肺も弱る）→ 六君子湯＋麦門冬湯、または補中益気湯",
    "ki+yu":"悲しめば則ち気消ゆ → 補中益気湯。不安・不眠があれば加味帰脾湯",
