      tcm:[["補中益気湯・六君子湯","医療用エキスあり（そのまま）"],["参苓白朮散","医療用エキスなし → 構成が近い啓脾湯、または六君子湯"]],
      alt:["清暑益気湯：汗・口渇など夏バテの名残が強い","半夏白朮天麻湯：頭重・めまいを伴う","真武湯：冷え・水様の下痢が強い"],
      caution:["六君子湯・補中益気湯・人参湯は甘草を含む","冷たい飲食を控えることが治療の一部"]
