      path:"秋は燥の季節で、燥邪は肺を傷りやすい（肺は潤を好み燥を嫌う）。肺は皮毛を主り、大腸と表裏をなすため、皮膚・鼻・喉・便にも乾燥が出る。",
      feat:"空咳・喉のイガイガ・痰が少ない。皮膚・鼻・口・目の乾燥、乾燥肌のかゆみ。便が硬い。",
      tongue:"舌 紅・少苔・乾燥／脈 細",
      main:"麦門冬湯／当帰飲子（乾燥肌）／滋陰降火湯",
      groups:[["潤肺降逆",["麦門冬湯"]],["滋陰潤肺（夜の咳・ほてり）",["滋陰降火湯"]],["皮膚の乾燥・かゆみ",["当帰飲子"]],["腸の乾燥",["麻子仁丸"]]],
