  cmpTitle:"夏→秋の4証 比較",
  cmpExtra:`<h3>秋の不調の機序</h3>
    <ul class="tight">
      <li><b>物悲しさ</b>：五行で秋＝金＝肺＝「悲・憂」。陽消陰長で、外向きの夏から内向きの秋へ心身がシフトする。悲しめば則ち気消ゆ。</li>
      <li><b>怠さ（秋バテ）</b>：夏の暑湿・冷たい飲食で脾胃が弱り（脾は肌肉・四肢を主る）、多汗で気も漏れた状態で秋の涼気を迎える。</li>
    </ul>
    <h3 style="margin-top:14px">秋の養生</h3>
    <div class="scroll"><table class="kv">
      <tr><th>目的</th><th>食</th><th>ツボ・生活</th></tr>
      <tr><td>脾胃を助ける</td><td>お粥・かぼちゃ・山芋・さつまいも。冷たい飲食を控える</td><td>太白・足三里・中脘を温める</td></tr>
      <tr><td>気を補う</td><td>山芋・鶏肉・なつめ・もち米</td><td>足三里・気海。汗をかきすぎない運動</td></tr>
      <tr><td>肺を潤す</td><td>白い食材：白きくらげ・梨・大根・蓮根・百合根・豆腐・はちみつ</td><td>太淵・尺沢。加湿・保湿・深呼吸</td></tr>
      <tr><td>憂いを和らげる</td><td>温かい汁物・旬のもの</td><td>膻中・内関・神門。早寝早起き・日中の散歩</td></tr>
    </table></div>
    <p class="hint">『素問』四気調神大論：秋三月は「早く臥し早く起き、鶏と倶に興き、志をして安寧ならしむ」。収斂の季節なので、無理に元気を出そうとせず、温めてゆったり過ごす。</p>`,
  pt:{
    hi:{t:"夏の疲れが胃腸に残った「秋バテ」",b:"夏の暑さや湿気、冷たい飲み物・食べ物で胃腸（脾）が弱り、食べたものから元気を作れず、体や手足が重だるくなっている状態です。<br><br>お薬で胃腸の働きを立て直し、元気を作る力を取り戻します。<br><br><b>養生のポイント</b>：温かく消化のよいもの（お粥・かぼちゃ・山芋）を／冷たいものを控える／足の内側の「太白」、すねの「足三里」を温める・押す"},
    ki:{t:"夏の汗で「元気が漏れた」だるさ",b:"夏にたくさん汗をかくと、汗と一緒に体のエネルギー（気）も外へ漏れ出てしまいます。エネルギー不足のまま秋の涼しさを迎えたため、気温の変化についていけず、だるさが残っている状態です。<br><br>お薬で気と潤いを補い、体を立て直します。<br><br><b>養生のポイント</b>：汗をかきすぎない軽い運動／山芋・鶏肉・なつめなどで元気を補う／しっかり眠る"},
    hai:{t:"秋の「乾燥」による喉・肌の不調",b:"秋は空気が乾燥し、東洋医学では「肺」が乾燥に弱いと考えます。肺は皮膚や鼻・喉ともつながっているため、空咳、喉のイガイガ、肌の乾燥やかゆみが出やすくなります。<br><br>お薬で体の内側から潤いを補います。<br><br><b>養生のポイント</b>：白い食材（白きくらげ・梨・大根・蓮根・はちみつ）で潤す／部屋の加湿／お風呂上がりはすぐ保湿／ゆっくり深呼吸"},
    yu:{t:"秋の「物悲しさ」と気力の低下",b:"東洋医学では、秋は「肺」の季節で、感情では「悲しみ・憂い」と結びつくと考えます。夏の活動的なエネルギーから、秋の静かなエネルギーへ切り替わる時期は、ふと寂しさや物悲しさを感じやすくなります。悲しみが続くと気力も消耗します。<br><br>お薬で心と体のエネルギーを補い、気持ちを穏やかにします。季節による自然な反応なので、無理に元気を出そうと焦らなくて大丈夫です。<br><br><b>養生のポイント</b>：早寝早起き／日中に散歩して光を浴びる／深呼吸／温かいものを食べてゆったり過ごす"}
  },
  formulas:["補中益気湯","六君子湯","啓脾湯","人参湯","胃苓湯","清暑益気湯","十全大補湯","麦門冬湯","滋陰降火湯","当帰飲子","麻子仁丸","甘麦大棗湯","加味帰脾湯","帰脾湯","半夏厚朴湯","香蘇散"]
